CREATE TABLE IF NOT EXISTS users (id BIGINT PRIMARY KEY AUTO_INCREMENT, uid VARCHAR(255) NOT NULL UNIQUE, lp_id VARCHAR(255) NOT NULL UNIQUE, username VARCHAR(255), mobile VARCHAR(255) UNIQUE, email VARCHAR(255) UNIQUE, open_id VARCHAR(255) UNIQUE, password VARCHAR(255), avatar_file_id INTEGER, background_file_id INTEGER, sex INTEGER NOT NULL DEFAULT 0, birthday DATETIME, city VARCHAR(255), job VARCHAR(255), company VARCHAR(255), signature VARCHAR(255), website VARCHAR(255), freezed BOOLEAN NOT NULL DEFAULT FALSE, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS files (id BIGINT PRIMARY KEY AUTO_INCREMENT, uid VARCHAR(255) NOT NULL UNIQUE, user_id INTEGER NOT NULL, name VARCHAR(255) NOT NULL, path VARCHAR(255), type VARCHAR(255) NOT NULL, file_md5 VARCHAR(255) NOT NULL, size INTEGER NOT NULL, `key` VARCHAR(255) NOT NULL UNIQUE, extension VARCHAR(255), width INTEGER, height INTEGER, blurhash VARCHAR(255), arthash VARCHAR(255), arthash_codec VARCHAR(255), lng REAL, lat REAL, country VARCHAR(255), country_code VARCHAR(255), province VARCHAR(255), city VARCHAR(255), district VARCHAR(255), address VARCHAR(255), altitude REAL, taken_at DATETIME, device_make VARCHAR(255), device_model VARCHAR(255), lens_model VARCHAR(255), f_number VARCHAR(255), exposure_time VARCHAR(255), iso INTEGER, focal_length VARCHAR(255), exif_raw BLOB, duration REAL, codec VARCHAR(255), bitrate INTEGER, frame_rate REAL, video_metadata BLOB, transcoding_task_id VARCHAR(255), is_private BOOLEAN NOT NULL DEFAULT FALSE, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS permission_spaces (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(255) NOT NULL UNIQUE, description VARCHAR(255), is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS permissions (id BIGINT PRIMARY KEY AUTO_INCREMENT, code VARCHAR(255) NOT NULL UNIQUE, name VARCHAR(255) NOT NULL, description VARCHAR(255), space_id INTEGER NOT NULL, position INTEGER NOT NULL, value INTEGER NOT NULL, module VARCHAR(255), is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS roles (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(255) NOT NULL UNIQUE, description VARCHAR(255), is_active BOOLEAN NOT NULL DEFAULT TRUE, is_system BOOLEAN NOT NULL DEFAULT FALSE, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS user_roles (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id INTEGER NOT NULL, role_id INTEGER NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, UNIQUE(user_id, role_id));
CREATE TABLE IF NOT EXISTS role_permissions (id BIGINT PRIMARY KEY AUTO_INCREMENT, role_id INTEGER NOT NULL, permission_id INTEGER NOT NULL, space_id INTEGER NOT NULL, value INTEGER NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, UNIQUE(role_id, permission_id));
CREATE TABLE IF NOT EXISTS user_permission_caches (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id INTEGER NOT NULL, space_id INTEGER NOT NULL, value INTEGER NOT NULL, expires_at DATETIME NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, UNIQUE(user_id, space_id));
CREATE TABLE IF NOT EXISTS multipart_uploads (id BIGINT PRIMARY KEY AUTO_INCREMENT, upload_id VARCHAR(255) NOT NULL UNIQUE, `key` VARCHAR(255) NOT NULL, md5 VARCHAR(255) NOT NULL, file_name VARCHAR(255) NOT NULL, file_size INTEGER NOT NULL, content_type VARCHAR(255), total_parts INTEGER NOT NULL, chunk_size INTEGER NOT NULL, user_id INTEGER, status VARCHAR(255) NOT NULL DEFAULT 'initiated', created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS uploaded_parts (id BIGINT PRIMARY KEY AUTO_INCREMENT, upload_id VARCHAR(255) NOT NULL, part_number INTEGER NOT NULL, e_tag VARCHAR(255) NOT NULL, size INTEGER NOT NULL, created_at DATETIME NOT NULL, UNIQUE(upload_id, part_number));
CREATE TABLE IF NOT EXISTS colors (id BIGINT PRIMARY KEY AUTO_INCREMENT, hex VARCHAR(255) NOT NULL UNIQUE, r INTEGER, g INTEGER, b INTEGER, created_at DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS file_colors (id BIGINT PRIMARY KEY AUTO_INCREMENT, file_id INTEGER NOT NULL, color_id INTEGER NOT NULL, is_primary BOOLEAN NOT NULL DEFAULT FALSE, rank INTEGER NOT NULL DEFAULT 0, percentage REAL, created_at DATETIME NOT NULL, UNIQUE(file_id, color_id));
CREATE TABLE IF NOT EXISTS video_variants (id BIGINT PRIMARY KEY AUTO_INCREMENT, file_id INTEGER NOT NULL, quality VARCHAR(255) NOT NULL, `key` VARCHAR(255) NOT NULL, format VARCHAR(255) NOT NULL DEFAULT 'mp4', size INTEGER, width INTEGER, height INTEGER, bitrate INTEGER, fps INTEGER, duration REAL, created_at DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS transcoding_tasks (id BIGINT PRIMARY KEY AUTO_INCREMENT, task_id VARCHAR(255) NOT NULL UNIQUE, file_id INTEGER, source_url VARCHAR(255) NOT NULL, webhook_url VARCHAR(255), provider VARCHAR(255) NOT NULL DEFAULT 'aliyun_mps', status VARCHAR(255) NOT NULL, resolutions BLOB, external_job_ids BLOB, results BLOB, error_msg VARCHAR(255), created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, completed_at DATETIME, deleted_at DATETIME);
